/// The section header: disclosure triangle, title in the micro-label face, the
/// current-state summary, and the Reset or Clear button pinned to the trailing
/// edge. The buttons are subviews so they eat their own clicks — everything
/// else toggles the group.
///
/// Spec §11 CI-9: a section EDITING an action (`marks.editing`) shows Clear,
/// only while the action keys one of its rows; otherwise it shows Reset, only
/// while it differs from its default. Both share the one slot, and at most
/// one is visible.
final class InspectorSectionHeader: NSView {
    var onToggle: (() -> Void)?
    var isExpanded = true {
        didSet { needsDisplay = true }
    }
    private var title = ""
    /// The last summary and marks drawn, so a refresh only redraws when one
    /// CHANGED — the panel refreshes on every document change and on every
    /// playhead move inside an action.
    private var lastSummary: String?
    private var marks = SectionMarks.empty
    /// Held so the summary can stop short of the VISIBLE one: they share the
    /// header's trailing end, and a summary drawn under a button would be
    /// unreadable. Clear is always built; Reset only for a section with one.
    private weak var resetButton: NSView?
    private weak var clearButton: NSView?
    /// The hover (#102, spec §11 CI-15 as amended): a second `DS.hoverFill`
    /// over the rest band, faded by its alpha, since a band drawn in
    /// `draw(_:)` cannot fade. The first subview, so Reset and Clear sit
    /// above it; it stops above the rule.
    let hoverBand = InspectorHeaderHoverBand()
    private(set) var isHovered = false

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
        hoverBand.translatesAutoresizingMaskIntoConstraints = false
        addSubview(hoverBand)
        NSLayoutConstraint.activate([
            hoverBand.leadingAnchor.constraint(equalTo: leadingAnchor),
            hoverBand.trailingAnchor.constraint(equalTo: trailingAnchor),
            hoverBand.topAnchor.constraint(equalTo: topAnchor),
            hoverBand.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -1),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorSectionHeader does not support NSCoder")
    }

    convenience init() {
        self.init(frame: .zero)
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: InspectorMetrics.headerHeight)
    }

    func configure(title: String, reset: (() -> Void)?, clear: @escaping () -> Void) {
        self.title = title
        clearButton = install(
            OptionButtonControl(title: "Clear", action: clear, enabled: { true }, onEdit: {}))
        if let reset {
            let button = install(
                OptionButtonControl(title: "Reset", action: reset, enabled: { true }, onEdit: {}))
            button.toolTip = "Reset this section to its defaults"
            resetButton = button
        }
        showButtons()
    }

    private func install(_ button: NSView) -> NSView {
        button.translatesAutoresizingMaskIntoConstraints = false
        addSubview(button)
        NSLayoutConstraint.activate([
            button.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
            button.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
        return button
    }

    /// CI-9's one slot: Clear while editing an action that keys the section,
    /// Reset while not editing and the section differs, else nothing.
    private func showButtons() {
        let editing = marks.editing
        clearButton?.isHidden = editing == nil || marks.keyed == 0
        clearButton?.toolTip = editing.map { "Remove this section from action \($0)" }
        resetButton?.isHidden = editing != nil || !marks.differs
    }

    /// The visible button's title — "Clear", "Reset" or nil.
    var buttonTitle: String? {
        if clearButton?.isHidden == false { return "Clear" }
        if resetButton?.isHidden == false { return "Reset" }
        return nil
    }

    /// The summary's ink: the action's when keyed, the body tier
    /// (`DS.textMuted`, spec §11 CI-9) when the section differs from its
    /// default, else faint.
    var summaryInk: NSColor {
        marks.keyed > 0 ? DS.action : marks.differs ? DS.textMuted : DS.textFaint
    }

    /// Takes the summary and the marks; redraws only when either moved.
    func refresh(summary: String?, marks: SectionMarks) {
        guard summary != lastSummary || marks != self.marks else { return }
        lastSummary = summary
        self.marks = marks
        showButtons()
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        onToggle?()
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Owner-filtered: a tooltip is a tracking area too (app/CLAUDE.md).
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: bounds, options: [.mouseEnteredAndExited, .activeInKeyWindow],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        setHovered(true)
    }

    override func mouseExited(with event: NSEvent) {
        setHovered(false)
    }

    /// The state at once, the band's alpha through `DS.animate` — set
    /// directly inside it, never through `animator()`, which animates even
    /// outside a group and so would ignore Reduce Motion.
    private func setHovered(_ hovered: Bool) {
        guard hovered != isHovered else { return }
        isHovered = hovered
        DS.animate(DS.hoverDuration) {
            hoverBand.alphaValue = hovered ? 1 : 0
        }
    }

    override func draw(_ dirtyRect: NSRect) {
        // **Pitfall:** `DS.hoverFill` is `quaternaryLabelColor`, which is
        // ALREADY about 10% ink — taking 0.35 of it left a 3.5% wash that is
        // invisible in the light appearance, so the header did not separate
        // from the rows under it. Drawn at its own alpha it is a quiet band
        // that reads in both appearances.
        DS.hoverFill.setFill()
        bounds.fill()
        DS.border.setFill()

        let label = NSAttributedString(
            string: tabs[index].title,
            attributes: [
                .font: DS.sans(11, weight: .semibold),
                .foregroundColor: isActive ? DS.textStrong : DS.textMuted,
            ])
        let count = badges.indices.contains(index) ? badges[index] : 0
        let mark = count > 0
            ? NSAttributedString(
                string: "◆\(count)",
                attributes: [.font: DS.mono(9, weight: .medium), .foregroundColor: DS.action])
            : nil
        let labelSize = label.size()
        let markSize = mark?.size() ?? .zero
        let gap: CGFloat = mark == nil ? 0 : 4
        let width = ceil(labelSize.width) + gap + ceil(markSize.width)
        let x = (rect.midX - width / 2).rounded()
        label.draw(at: NSPoint(x: x, y: rect.midY - labelSize.height / 2))
        mark?.draw(
            at: NSPoint(
                x: x + ceil(labelSize.width) + gap, y: rect.midY - markSize.height / 2))
    }
}

/// The Clip tab's pinned block (the clip inspector handoff's "Pinned action
/// lane block", road map 9 §1 and §3): the selection header, the action lane
/// and the sub-tab strip, stacked, and under them the matte note when the
/// pane gives one (spec §11 MT-7, `ClipPane+Matte.swift`). One
/// `OptionControl`, because the pane has one header slot
/// (`InspectorPaneView.makeHeader()`), refreshed with it and hosted ABOVE the
/// scroll view by the controller (`pinnedBlock`).
final class ClipHeaderBlock: NSView, OptionControl {
    private let header: ClipSelectionHeaderView
    private let lane: ActionLaneView
    private let strip: ClipSubTabsView?
    private let noteLabel: InspectorNoteLabel?

    /// `note` is given only while it has words: the pane's structure
    /// signature carries whether it shows, so its coming or going rebuilds
    /// the block, and a refresh only re-reads its words.
    init(
        binding: InspectorBinding, inspector: InspectorViewController?,
        subTabs: ClipSubTabsView?, note: (() -> String?)? = nil
    ) {
        header = ClipSelectionHeaderView(binding: binding)
        lane = ActionLaneView(binding: binding, inspector: inspector)
        strip = subTabs
        noteLabel = note.map { InspectorNoteLabel(wraps: true, note: $0) }
        super.init(frame: .zero)
        var views: [NSView] = [header, lane]
        if let subTabs { views.append(subTabs) }
        var above = topAnchor
        for view in views {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
            NSLayoutConstraint.activate([
                view.topAnchor.constraint(equalTo: above),
                view.leadingAnchor.constraint(equalTo: leadingAnchor),
                view.trailingAnchor.constraint(equalTo: trailingAnchor),
            ])
            above = view.bottomAnchor
        }
        if let label = noteLabel {
            // A sentence of two lines at the panel's width: it wraps.
            label.translatesAutoresizingMaskIntoConstraints = false
            addSubview(label)
            NSLayoutConstraint.activate([
                label.topAnchor.constraint(equalTo: above, constant: 6),
                label.leadingAnchor.constraint(
                    equalTo: leadingAnchor, constant: InspectorMetrics.inset),
                label.trailingAnchor.constraint(
                    equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
            ])
            label.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -8).isActive = true
        } else {
            above.constraint(equalTo: bottomAnchor).isActive = true
        }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ClipHeaderBlock does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// The lane, for a probe.
    var actionLane: ActionLaneView { lane }

    /// The sub-tab strip, for a probe.
    var subTabsView: ClipSubTabsView? { strip }

    /// The matte note's words as shown, for a probe; nil when it has none.
    var noteText: String? { noteLabel.flatMap { $0.isHidden ? nil : $0.stringValue } }

    func refresh() {
        header.refresh()
        lane.refresh()
        strip?.refresh()
        noteLabel?.refresh()
    }
}
    /// Back to the top of the panel.
    ///
    /// Deliberately NOT called after every rebuild: a rebuild also happens
    /// when a filter is added, an action appears or a transition comes and
    /// goes, and yanking the panel to the top under a user who is dialling a
    /// filter halfway down it would trade one bug for another. The two moments
    /// the design names — a different clip, a different tab — are the two that
    /// ask for it.
    ///
    /// The pane is flipped (`InspectorPaneView.isFlipped`), so the top is
    /// y = 0 whatever the content height is, and this needs no layout pass to
    /// have run first.
    private func scrollToTop() {
        scroll.contentView.scroll(to: .zero)
        scroll.reflectScrolledClipView(scroll.contentView)
    }

    // MARK: - Refresh

    /// The ONE path from a changed document to the panel, called by
    /// `EditorViewController.refreshFromDocument`. `isLive` suppresses
    /// rebuilds: mid-gesture the values change but the shape does not.
    func refresh(isLive: Bool) {
        guard isViewLoaded else { return }
        refusalStrip.clearIfStale(document?.editedProject)
        binding.invalidate()
        let clips = selectedClips

        // Picking a clip in the timeline or on the canvas asks about THAT
        // clip, so the panel answers about it — one selection model, and the
        // panel is one of its three views (the timeline bar's block and the
        // canvas handles are the others).
        // Switched in place rather than through `select(_:)`: that one starts
        // a refresh of its own, and this one is already running — with
        // `isLive` in hand, which a nested call would drop.
        let ids = clips.map { $0.id }
        // A different clip and a different tab are the two things that make
        // the panel a different list, so they are the two that send it back to
        // the top; everything else leaves the user where they were reading.
        var toTop = false
        if ids != lastSelection {
            lastSelection = ids
            toTop = true
            (pane(for: .clip) as? ClipPane)?.forgetSubTab()
            if !clips.isEmpty, tab == .media || tab == .document {  // AI-14
                tab = .clip
                buildTabs()
            }
        }

        let pane = pane(for: tab)
        if showPane(pane) { toTop = true }
        let signature = pane.structureSignature
        // A rebuild replaces every control, so it must never happen under a
        // live gesture — the slider being dragged would vanish mid-drag.
        if signature != lastSignature, !isLive, document?.isLiveEditing != true {
            lastSignature = signature
            pane.rebuild()
            installPinned(pane.pinnedBlock)
        }
        pane.refresh()
        if toTop { scrollToTop() }
    }
}
